use super::*;

/// Parse a [`FieldType`] from its lowercase string; anything unknown falls back to `String`.
pub fn field_type_from_str(s: &str) -> FieldType {
    match s {
        "number" => FieldType::Number,
        "bool" | "boolean" => FieldType::Bool,
        "date" => FieldType::Date,
        "money" => FieldType::Money,
        "enum" => FieldType::Enum,
        "ref" => FieldType::Ref,
        _ => FieldType::String,
    }
}
